parameters.jsCode:
// Feuilles SOURCE = celles dont le nom commence par un code NAF (ex. "78.20Z ...").
// Detectees dynamiquement : une nouvelle feuille NAF est prise en compte sans toucher au code.
// Exclut de fait : Annuaire (destination), Notes_Claire, Methode.
const MOTIF = /^\d{2}\.\d{2}/;

const brut = $('Lister feuilles').first().json;
const src  = brut.body ?? brut;                 // fullResponse -> { body, headers, statusCode }
const feuilles = Array.isArray(src.value) ? src.value : [];

if (!feuilles.length) {
  throw new Error('Liste des feuilles vide. Reponse brute de "Lister feuilles" : ' + JSON.stringify(brut).slice(0, 900));
}

const sources = feuilles
  .filter(w => w && w.name && w.id && MOTIF.test(String(w.name).trim()))
  .sort((a, b) => (a.position ?? 0) - (b.position ?? 0))
  .map(w => ({ json: { sheetName: String(w.name).trim(), sheetId: w.id } }));

if (!sources.length) {
  throw new Error('Aucune feuille source detectee (le nom doit commencer par un code NAF). Feuilles du classeur : ' + feuilles.map(w => w.name).join(' | '));
}

return sources;

// Reglages centraux du radar commercial Apollo.
// !! Cle API Apollo en clair : a deplacer dans une credential n8n "Header Auth" (x-api-key), puis rotater.
const WORKBOOK_ID = '22002ED2757F43B18C70ACEB7FAB3A78';

return [{
  json: {
    APOLLO_API_KEY: 'REMPLACER',
    PAYS: ['France'],

    WORKBOOK_ID,
    GRAPH: 'https://graph.microsoft.com/v1.0/me/drive/items/' + WORKBOOK_ID + '/workbook',
    FEUILLE_ANNUAIRE: 'Annuaire',

    // ===== QUALIFICATION IA =====
    // /!\ 2026-08-06 : compte1 ET compte2 sont a court de quota hebdomadaire (429).
    //     Remettre a true des qu'un compte est de nouveau disponible, ou apres avoir
    //     depose une cle API dans /opt/n8n/secrets/claude/api-key (rang 2 du wrapper).
    // QUALIFICATION_IA : appelle le CLI Claude Code (~17 s, ~0,05 $ de quota par societe).
    //                    Si false, la colonne Secteur reste VIDE.
    // IA_SCORING       : false -> secteur metier + site web uniquement.
    //                    true  -> ajoute le score /10 et CORE/EDGE/OUT dans apollo_statut.
    QUALIFICATION_IA: true,
    IA_SCORING: false,
    MODELE_IA: 'sonnet',
    TIMEOUT_IA_MS: 270000,
    SEUIL_CORE: 7,
    MOTIF_IA: true,


    // ===== SELECTION DES CONTACTS =====
    // Priorite absolue a l'email : d'abord tous les contacts joignables, LinkedIn ensuite.
    STATUTS_EMAIL_ACCEPTES: ['verified', 'likely to engage', 'extrapolated'],
    INCLURE_SANS_EMAIL: true,
    SEUIL_COMPLEMENT_LINKEDIN: 10,
    SENIORITES: ['owner','founder','c_suite','partner','vp','head','director','manager','senior','entry'],

    // ===== PLAFONDS =====
    // 1 societe par run : mode TEST. Monter seulement apres validation.
    MAX_SOCIETES_PAR_RUN:10,
    // 30 contacts par entreprise, 2 par fonction en priorite ; si une fonction est vide,
    // on bouche avec les autres pour atteindre 10 quand meme.
    MAX_PROSPECTS_PAR_SOCIETE: 10,
    MAX_PAR_FONCTION: 2,

    SEUIL_MATCH_SOCIETE: 0.6,
  },
}];

// Transforme la reponse Graph "usedRange" en lignes exploitables, en conservant le
// NUMERO DE LIGNE reel dans la feuille : c'est lui qui permet d'ecrire apollo_statut
// dans la bonne cellule, sans dependre d'une recherche cote n8n.
const b   = $('Boucle feuilles').all()[0]?.json || {};
const rep = $input.first()?.json || {};
const src = rep.body ?? rep;

const values  = Array.isArray(src.values) ? src.values : [];
const address = String(src.address || '');      // ex : "'78.20Z Intérim'!A1:L7"
if (values.length < 2) return [];               // en-tetes seuls, ou feuille vide

// Colonne + ligne de depart de la zone utilisee
const m = address.match(/!\$?([A-Z]+)\$?(\d+)/i);
const colDepart   = m ? m[1].toUpperCase() : 'A';
const ligneDepart = m ? parseInt(m[2], 10) : 1;

const colVersNum = s => [...s].reduce((a, c) => a * 26 + (c.charCodeAt(0) - 64), 0);
const numVersCol = n => { let s = ''; while (n > 0) { const r = (n - 1) % 26; s = String.fromCharCode(65 + r) + s; n = Math.floor((n - 1) / 26); } return s; };

const entetes   = (values[0] || []).map(h => String(h ?? '').trim());
const iApollo   = entetes.indexOf('apollo_statut');
const colApollo = iApollo >= 0 ? numVersCol(colVersNum(colDepart) + iApollo) : '';

const out = [];
values.slice(1).forEach((ligne, idx) => {
  const o = {};
  let vide = true;
  entetes.forEach((h, k) => {
    if (!h) return;
    const v = ligne[k];
    o[h] = (v === null || v === undefined) ? '' : String(v).trim();
    if (o[h] !== '') vide = false;
  });
  if (vide) return;                             // ligne totalement vide -> ignoree
  o._sheet     = b.sheetName || '';
  o._sheetId   = b.sheetId || '';
  o._rowNumber = ligneDepart + 1 + idx;         // +1 : 1re ligne de la zone = les en-tetes
  o._colApollo = colApollo;
  out.push({ json: o });
});

return out;

// Normalise les lignes societe, deduplique, ordonne par rendement, et plafonne le nombre par run.
//
// ATTENTION : les feuilles n'ont PAS toutes le meme schema.
//   78.20Z Interim -> Classe | Nom / enseigne | Raison sociale (SIRENE) | SIREN | NAF | ...
//   les 8 autres   -> Code NAF | Nom | SIREN | Commune | ... | Tranche effectif | ...
// Chaque information est donc lue par ordre de preference sur plusieurs noms de colonne.
const cfg = $('Config').first().json;
const MAX = cfg.MAX_SOCIETES_PAR_RUN || 15;
const t = s => String(s ?? '').trim();
// premiere valeur non vide parmi plusieurs colonnes possibles ('-' = valeur absente cote source)
const prem = (r, ...cles) => {
  for (const c of cles) { const v = t(r[c]); if (v && v !== '-') return v; }
  return '';
};

// --- Nom envoye a Apollo ---
// Apollo indexe des noms COMMERCIAUX, les feuilles portent la raison sociale du registre.
// Mesures du 07/08 :
//   "SOCIETE AIR FRANCE"                             -> 0 resultat ; "Air France" -> 52.
//   "AIR CARAIBES (AIR CARAIBES CHARTER AIR GUAD...)" -> 0 ; SIRENE accole les enseignes du groupe.
//   "AMERICAN AIRLINES INC", "BRITISH AIRWAYS PLC"    -> 0 ; formes juridiques anglo-saxonnes.
//   "TURK HAVA YOLLARI AO - TURKISH AIR LINES"        -> 0 ; double denomination separee par un tiret.
// On coupe donc a la parenthese, au slash et au tiret entoure d'espaces, puis on retire la forme
// juridique en TETE et en QUEUE. On ne touche JAMAIS a un mot pouvant appartenir a la marque :
// FRANCE, GROUPE, COMPAGNIE, AIR, AIRWAYS, AIRLINES restent.
const FORMES = ['SOCIETE', 'STE', 'SA', 'SAS', 'SASU', 'SARL', 'EURL', 'SNC', 'SCS', 'SCA',
                'SASP', 'GIE', 'EARL', 'SCOP', 'SELARL', 'SCM',
                'INC', 'LTD', 'LIMITED', 'PLC', 'LLC', 'CORP', 'CORPORATION',
                'GMBH', 'AG', 'BV', 'NV', 'SPA', 'SRL', 'AB', 'AS', 'OY', 'PTE'];
function nomRecherche(s) {
  let base = String(s || '');
  const par = base.indexOf('(');
  if (par > 0) base = base.slice(0, par);          // enumeration d'enseignes : on garde la 1re
  base = base.split('/')[0];                       // "X / Y"
  base = base.split(/\s+-\s+/)[0];                 // "X - Y" (double denomination)
  const m = base.replace(/[.,]/g, ' ').replace(/\s+/g, ' ').trim().split(' ');
  let bouge = true;
  while (bouge && m.length > 1) {
    bouge = false;
    const tete = m[0].toUpperCase().replace(/[^A-Z]/g, '');
    if (FORMES.includes(tete)) { m.shift(); bouge = true; continue; }
    const queue = m[m.length - 1].toUpperCase().replace(/[^A-Z]/g, '');
    if (FORMES.includes(queue)) { m.pop(); bouge = true; }
  }
  return m.join(' ').trim();
}

const vus = new Set();
const out = [];
const ignorees = [];

for (const it of $input.all()) {
  const r = it.json || {};

  const raison   = prem(r, 'Raison sociale (SIRENE)', 'Raison sociale', 'Nom');
  const enseigne = prem(r, 'Nom / enseigne', 'Enseigne', 'Nom');
  const nom = raison || enseigne;

  const sheet     = t(r._sheet);
  const sheetId   = t(r._sheetId);
  const colApollo = t(r._colApollo);
  const rowNumber = Number(r._rowNumber || 0);

  // Ligne sans nom exploitable : on ne peut pas interroger Apollo. On la recense
  // au lieu de la laisser disparaitre en silence.
  if (!nom) { ignorees.push(sheet + ' L' + rowNumber); continue; }

  const siren = prem(r, 'SIREN');
  const cle = siren || (sheet + '|' + nom.toUpperCase());
  if (vus.has(cle)) continue;
  vus.add(cle);

  // Reperage exact de la cellule apollo_statut a mettre a jour en fin de traitement.
  // Pas de repli silencieux : sans reperage complet la societe ne serait jamais marquee
  // et repasserait a chaque run.
  if (!sheetId || !colApollo || !rowNumber) {
    throw new Error('Reperage incomplet pour "' + nom + '" (feuille "' + sheet + '") : '
      + 'sheetId=' + (sheetId || 'vide')
      + ' colonne=' + (colApollo || 'vide — la colonne apollo_statut existe-t-elle dans cette feuille ?')
      + ' ligne=' + rowNumber);
  }

  // On cherche sur l'enseigne nettoyee en priorite : c'est le nom sous lequel Apollo connait
  // l'entreprise. La raison sociale ne sert que de repli.
  const cherche = nomRecherche(enseigne) || nomRecherche(raison) || nom;

  // Nom AFFICHE dans l'Annuaire : lui aussi debarrasse de l'enumeration entre parentheses,
  // sinon la RH lit "AIR CARAIBES (AIR CARAIBES CHARTER AIR GUADELOUPE ...)" dans sa colonne.
  const affiche = (enseigne || raison).split('(')[0].trim() || (enseigne || raison);

  out.push({ json: {
    _nom_recherche: cherche,
    _nom_brut: nom,
    _nom_affiche: affiche,
    _raison: raison,
    _enseigne: enseigne,
    _siren: siren,
    _naf: prem(r, 'NAF', 'Code NAF'),
    _classe: prem(r, 'Classe') || sheet,
    _commune: prem(r, 'Commune'),
    _taille: prem(r, 'Taille'),
    _effectif: prem(r, 'Tranche effectif'),
    _sheet: sheet,
    _sheetId: sheetId,
    _colApollo: colApollo,
    _rowNumber: rowNumber,
  }});
}

if (!out.length && ignorees.length) {
  throw new Error('Aucune societe exploitable : ' + ignorees.length
    + ' ligne(s) sans nom reconnaissable. Exemples : ' + ignorees.slice(0, 5).join(', ')
    + '. Verifie les en-tetes de ces feuilles.');
}

// --- ORDRE DE PASSAGE : rendement Apollo decroissant ---
// Mesure du 07/08 : interroger une societe coute 1 credit, QU'ELLE SOIT TROUVEE OU NON.
// Tri STABLE : a l'interieur d'une feuille, l'ordre des lignes du classeur est conserve.
const ORDRE = cfg.ORDRE_FEUILLES || [
  '51.10Z', '52.29A-B', '51.21Z', '56.29A-B', '52.23Z',
  '80.10Z', '81.21-22Z', '85.59A', '78.20Z',
];
const rang = s => {
  const i = ORDRE.findIndex(p => String(s || '').indexOf(p) === 0);
  return i < 0 ? ORDRE.length : i;
};
out.sort((a, b) => rang(a.json._sheet) - rang(b.json._sheet));

const res = out.slice(0, MAX);
res.forEach(i => {
  i.json._candidates_total = out.length;
  i.json._ignorees = ignorees.length;
  i.json._ignorees_exemples = ignorees.slice(0, 5);
});
return res;

// Choisit la meilleure correspondance Apollo pour la societe courante, avec seuil de similarite.
const cfg   = $('Config').first().json;
const src   = $('Boucle societes').all()[0].json;
const seuil = cfg.SEUIL_MATCH_SOCIETE ?? 0.6;

const rep  = $input.first()?.json || {};
const rsp  = rep.body ?? rep;
const orgs = rsp.organizations || rsp.accounts || [];

const norm0 = s => String(s || '').toUpperCase().normalize('NFD')
  .replace(/[̀-ͯ]/g, '').replace(/[^A-Z0-9]/g, '');

// --- 1er ou 2e essai ? ---
// Apollo rejoue la requete dans "breadcrumbs" : on y lit le nom REELLEMENT interroge et on le
// compare a celui de la societe. S'ils different, le rattrapage IA a fourni un nom -> 2e essai.
// !! Ne PAS se fier a $('Parser nom').all() : dans la boucle ce noeud renvoie son DERNIER run,
// pas celui de la societe courante (vecu le 07/08 : la 1re societe declenchait le rattrapage et
// les 9 suivantes heritaient de essai=2, donc plus aucun rattrapage possible).
const bc = (rsp.breadcrumbs || []).find(b => b && b.signal_field_name === 'q_organization_name');
const nomInterroge = bc ? String(bc.value || '') : '';
const estRattrapage = !!nomInterroge && norm0(nomInterroge) !== norm0(src._nom_recherche);
const essai = estRattrapage ? 2 : 1;
const nomIA = estRattrapage ? nomInterroge : '';

const FORMES = /\b(SAS|SASU|SARL|EURL|SA|SNC|SCI|SCOP|GIE|GROUPE|GROUP|HOLDING|INTERNATIONAL|COMPANY|LIMITED|LTD|LLC|INC|PLC|CORP|GMBH|BV|NV|AG|CO)\b/g;
const norm = s => String(s || '')
  .toUpperCase()
  .normalize('NFD').replace(/[̀-ͯ]/g, '')
  .replace(/[^A-Z0-9 ]/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();
const tokens = s => norm(s).replace(FORMES, ' ').split(/\s+/).filter(x => x.length > 1);

function similarite(a, b) {
  const A = new Set(tokens(a)), B = new Set(tokens(b));
  if (!A.size || !B.size) return 0;
  const inter = [...A].filter(x => B.has(x)).length;
  const jaccard = inter / new Set([...A, ...B]).size;
  const ca = [...A].join(''), cb = [...B].join('');
  const contenu = (ca && cb && (ca.includes(cb) || cb.includes(ca))) ? 0.85 : 0;
  return Math.max(jaccard, contenu);
}

// --- Indice SECTEUR : NAF de la feuille vs NAICS/SIC de la fiche Apollo ---
// C'est le signal le plus discriminant dont on dispose. Apollo heberge au moins trois societes
// nommees exactement "Corsair" ; aucune ne porte de marqueur francais, donc le choix etait
// arbitraire. Le code d'activite les separe sans ambiguite : la compagnie aerienne est en NAICS
// 4811 / SIC 4512, Corsair Gaming en electronique (334xxx / 3571).
// Correspondances calees sur les 9 feuilles du classeur. Une feuille inconnue -> aucun effet.
const NAF_NAICS = {
  '51.10': ['4811', '4812'],                    // transport aerien de passagers
  '51.21': ['4811', '4812', '4885'],            // fret aerien
  '52.23': ['4881', '4885', '4879'],            // services auxiliaires / assistance aeroportuaire
  '52.29': ['4885', '4884', '4931', '4889'],    // organisation du transport de fret
  '56.29': ['7223', '7225', '3118'],            // restauration collective / catering
  '78.20': ['5613'],                            // travail temporaire
  '80.10': ['5616'],                            // activites de securite privee
  '81.21': ['5617'], '81.22': ['5617'],         // nettoyage
  '85.59': ['6114', '6115', '6116', '6113'],    // formation
  '33.16': ['4881', '3364'],                    // maintenance aeronautique
};
const NAF_SIC = {
  '51.10': ['4512', '4513'], '51.21': ['4512', '4513', '4731'],
  '52.23': ['4581'], '52.29': ['4731'], '56.29': ['5812'],
  '78.20': ['7363'], '80.10': ['7381', '7382'], '81.21': ['7349'], '81.22': ['7349'],
  '85.59': ['8249', '8299'], '33.16': ['3728', '4581'],
};
function attendus(table) {
  const c = String(src._naf || '').toUpperCase().replace(/[^0-9]/g, '');   // "5110Z" -> "5110"
  if (c.length < 4) return null;
  return table[c.slice(0, 2) + '.' + c.slice(2, 4)] || null;
}
const NAICS_OK = attendus(NAF_NAICS);
const SIC_OK   = attendus(NAF_SIC);

function indiceSecteur(o) {
  const colle = (codes, prefs) => !!prefs && (codes || []).some(
    c => prefs.some(p => String(c).indexOf(p) === 0));
  let n = 0;
  if (colle(o.naics_codes, NAICS_OK)) n += 2;
  if (colle(o.sic_codes, SIC_OK)) n += 1;
  return n;
}

// --- Indice "entite francaise", simple appoint ---
// Deux erreurs deja commises ici, a ne pas refaire :
//   1) compter la langue -> un multinational liste le francais parce que son site est traduit.
//      Corsair Gaming decrochait ainsi un point et battait les vrais candidats.
//   2) reduire le bassin aux candidats francais des qu'il en existe un -> "CORSAIR" partait sur
//      "CORSAIR SYSTEM" (societe francaise sans rapport, similarite 0,85) au lieu des "Corsair"
//      a 1,00. Une preference ne doit JAMAIS faire perdre en similarite.
function indiceFrance(o) {
  const dom = String(o.primary_domain || o.website_url || '').toLowerCase();
  const tel = String(o.sanitized_phone || o.phone || '').replace(/\D/g, '');
  let n = 0;
  if (/\.fr(\b|\/|$)/.test(dom)) n += 2;
  if (tel.indexOf('33') === 0) n += 2;
  return n;
}

const notes = orgs.map(o => ({
  o,
  s: Math.max(
    similarite(src._raison, o.name),
    similarite(src._enseigne, o.name),
    nomIA ? similarite(nomIA, o.name) : 0
  ),
  a: indiceSecteur(o),
  f: indiceFrance(o),
}));

// Ordre de decision : similarite de nom, puis SECTEUR, puis France.
// La similarite prime toujours ; secteur et pays ne departagent que des ex aequo stricts.
const sMax = notes.reduce((m, x) => Math.max(m, x.s), 0);
const tete = notes.filter(x => x.s >= sMax - 0.0001);

let best = null, ia = -1, iF = -1;
for (const x of tete) {
  if (x.a > ia || (x.a === ia && x.f > iF)) { ia = x.a; iF = x.f; best = x.o; }
}

const meilleur = sMax;
const ok = !!best && meilleur >= seuil;

return [{ json: {
  ...src,
  _essai: essai,
  _nom_ia: nomIA,
  _nom_interroge: nomInterroge,
  _nom_recherche: nomIA || src._nom_recherche,
  _match: ok,
  _match_score: Math.round(meilleur * 100) / 100,
  _indice_secteur: ia < 0 ? 0 : ia,
  _indice_france: iF < 0 ? 0 : iF,
  _ex_aequo: tete.length,
  _naics_attendus: NAICS_OK,
  // id bidon si pas de match : la recherche de personnes renverra 0 resultat (appel gratuit)
  _org_id: ok ? best.id : '000000000000000000000000',
  _org_nom: ok ? best.name : '',
  _domaine: ok ? (best.primary_domain || '') : '',
  _apollo_statut: ok ? 'TRUE' : 'NO_MATCH',
  _candidats: orgs.map(o => o.name + '[s' + indiceSecteur(o) + 'f' + indiceFrance(o) + ']').slice(0, 5).join(' | ')
}}];

// Grosse societe (>100 contacts) : la recherche large est tronquee, on rejoue les filtres
// Apollo natifs. Les 10 fonctions demandees sont fusionnees en 6 requetes : celles qui
// partagent le meme couple (departement, niveau hierarchique).
// person_titles = OR + correspondance partielle ; croise en AND avec departement et seniorite.
//
// CHAQUE bloc est joue DEUX FOIS, et c'est deliberе :
//   passe 1 (person_locations = France) -> les decideurs francais, cherches dans la TOTALITE du
//     vivier. Indispensable : British Airways compte 20 213 contacts chez Apollo, soit 203 pages,
//     et la recherche large n'en voit que la premiere, un echantillon arbitraire sans Francais.
//   passe 2 (sans filtre pays) -> rattrape les profils dont le pays n'est PAS renseigne, qu'un
//     filtre serveur exclurait silencieusement. "Filtre localisation ciblees" ne gardera d'eux
//     que ceux sans pays : un contact affiche en Angleterre reste ecarte.
// Les recherches de personnes sont GRATUITES (0 credit), seul le temps double.
const org  = $('Choisir societe').first().json._org_id;
const PAYS = $('Config').first().json.PAYS || ['France'];

const BLOCS = [
  // DRH / RRH
  { titres: ['DRH','RRH','RH','HR','Talent','People','Ressources Humaines','Human Resources','HRBP','CHRO','Capital Humain'],
    depts: ['master_human_resources'], sen: ['manager','director','vp','head','c_suite'] },
  // Recrutement + Formation (memes departement et niveaux, 'entry' inclus pour les Charge(e) de...)
  { titres: ['Recrutement','Recruiting','Recruiter','Recruteur','Talent Acquisition','Hiring','Integration','Formation','Training','Learning','L&D','Competences'],
    depts: ['master_human_resources'], sen: ['manager','director','head','senior','entry'] },
  // Direction generale / de site -- aucun departement Apollo ne correspond
  { titres: ['Directeur General','General Manager','Managing Director','CEO','Country Manager','Branch Manager','Regional Director','Site Manager','Gerant','President','Directeur de site','Directeur regional','Directeur de filiale',"Chef d'etablissement"],
    depts: null, sen: ['owner','founder','c_suite','partner','vp'] },
  // Achats + Operations / Exploitation
  { titres: ['Achats','Acheteur','Procurement','Sourcing','Purchasing','Fournisseurs','Exploitation','Operations','Escale','Handling','Station Manager','Ground Operations','Chef de base'],
    depts: ['master_operations'], sen: ['manager','director','vp','head','c_suite'] },
  // Planning + Surete + Qualite/QHSE
  { titres: ['Planning','Planification','Scheduling','Workforce','Roster','Ordonnancement','Surete','Securite','Security','Safety','Qualite','Quality','QHSE','QSE','HSE','EHS'],
    depts: ['master_operations'], sen: ['manager','director','head','senior','entry'] },
  // DAF / Controle de gestion
  { titres: ['Financier','Finance','Controller','Controle de gestion','DAF','RAF','CFO','Comptable'],
    depts: ['master_finance'], sen: ['manager','director','vp','c_suite'] },
];

const sorties = [];
for (const b of BLOCS) {
  for (const avecPays of [true, false]) {
    const q = {
      page: 1, per_page: 100,
      organization_ids: [org],
      person_titles: b.titres,
      person_seniorities: b.sen,
    };
    if (avecPays) q.person_locations = PAYS;
    if (b.depts) q.person_department_or_subdepartments = b.depts;
    sorties.push({ json: { _query: q, _avec_pays: avecPays } });
  }
}
return sorties;

// Classe les personnes trouvees dans les 10 fonctions cibles, deduplique, selectionne, et
// prepare les lots pour /people/bulk_match.
//
// REGLE DE COUT : seuls les contacts dont Apollo annonce un email exploitable partent a
// l'enrichissement (1 credit = 1 email revele). Un contact 'unavailable' n'a PAS d'email
// chez Apollo : l'enrichir ne renverrait rien et couterait quand meme.
const cfg = $('Config').first().json;
const soc = $('Choisir societe').first().json;
const MAX = cfg.MAX_PROSPECTS_PAR_SOCIETE || 10;
const MAX_PAR_FONCTION = cfg.MAX_PAR_FONCTION || 2;
const OK_EMAIL = cfg.STATUTS_EMAIL_ACCEPTES || ['verified','likely to engage','extrapolated'];
const INCLURE_SANS_EMAIL = cfg.INCLURE_SANS_EMAIL !== false;
const SEUIL_COMPLEMENT = cfg.SEUIL_COMPLEMENT_LINKEDIN ?? MAX;

// Les 10 FONCTIONS cibles. Chaque bloc regroupe tous les synonymes d'UN MEME poste.
//   niveau 1 = qui SIGNE | niveau 2 = qui DECLENCHE le besoin | niveau 3 = qui PILOTE
// Regles ecrites SANS accent : les titres sont normalises avant test.
const BLOCS = [
  { cle:'RH', niveau:1, poids:100,
    titres:[/\bdrh\b/,/\brrh\b/,/\brh\b/,/ressources? humaines?/,/\bhr\b/,/human resources/,/\bpeople\b/,/talent management/,/\bchro\b/,/\bhrbp\b/,/business partner/,/capital humain/],
    depts:['master_human_resources'], sen:['manager','director','vp','head','c_suite','owner','founder','partner','senior','entry'] },
  { cle:'RECRUTEMENT', niveau:1, poids:95,
    titres:[/recrut/,/recruit/,/talent acquisition/,/staffing/,/hiring/,/integration/],
    titresSiDept:{ regex:[/sourcing/], depts:['master_human_resources'] },
    exclure:[/achat/,/procurement/,/purchasing/,/supplier/,/fournisseur/,/\bit\b/,/software/,/technique/,/systeme/,/\bdata\b/,/\bapi\b/,/developp/],
    depts:['master_human_resources'], sen:['manager','director','head','senior','vp','c_suite','entry'] },
  { cle:'DIRECTION', niveau:1, poids:92,
    titres:[/directeur general/,/directrice general/,/\bdg\b/,/\bpdg\b/,/gerant/,/president/,/\bceo\b/,/managing director/,/general manager/,/country manager/,/branch manager/,/agency (manager|director)/,/regional director/,/site (director|manager)/,/direct(eur|rice) (de site|d.agence|de filiale|regional)/,/chef d.etablissement/,/\bfounder\b/,/\bowner\b/,/co-?fondateur/],
    depts:null, sen:['owner','founder','c_suite','partner','vp','head','director','manager'] },
  { cle:'ACHATS', niveau:1, poids:85,
    titres:[/achat/,/acheteu/,/procurement/,/purchasing/,/sourcing/,/category manager/,/fournisseur/,/vendor manager/,/\bcpo\b/],
    depts:['master_operations'], sen:['manager','director','vp','head','c_suite','senior'] },
  { cle:'OPERATIONS', niveau:2, poids:78,
    titres:[/exploitation/,/operations?/,/\bops\b/,/escale/,/handling/,/station manager/,/ground operations/,/chef de base/,/\bcoo\b/,/\bpiste\b/],
    depts:['master_operations'], sen:['manager','director','vp','head','c_suite'] },
  { cle:'PLANNING', niveau:2, poids:72,
    titres:[/plan+ing/,/planification/,/scheduling/,/workforce/,/roster/,/ordonnancement/],
    depts:['master_operations'], sen:['manager','director','head','senior','entry'] },
  { cle:'SURETE', niveau:2, poids:66,
    titres:[/surete/,/securite/,/\bsecurity\b/,/\bsafety\b/],
    exclure:[/qualite/,/qhse/,/\bqse\b/,/environnement/],
    depts:['master_operations'], sen:['manager','director','head'] },
  { cle:'FORMATION', niveau:3, poids:56,
    titres:[/formation/,/training/,/learning/,/l&d/,/competences/],
    depts:['master_human_resources'], sen:['manager','director','head','senior','entry'] },
  { cle:'FINANCE', niveau:3, poids:52,
    titres:[/financier/,/financiere/,/\bfinance\b/,/controller/,/control(e|eur) de gestion/,/\bdaf\b/,/\braf\b/,/\bcfo\b/,/comptab/,/administratif et financier/],
    depts:['master_finance'], sen:['manager','director','vp','head','c_suite'] },
  { cle:'QUALITE', niveau:3, poids:48,
    titres:[/qualite/,/quality/,/\bqhse\b/,/\bqse\b/,/\bhse\b/,/\behs\b/],
    depts:['master_operations'], sen:['manager','director','head','senior','entry'] },
];

const BONUS_SEN = { c_suite:12, owner:12, founder:12, partner:8, vp:8, head:7, director:6, manager:3, senior:1, entry:0 };
const norm = s => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');

// --- Collecte : recherche large + recherches ciblees, dedupliquees par id ---
let larges = [];
try { larges = $('Apollo - Personnes').all(); } catch (e) { larges = []; }
const parId = new Map();
for (const r of [...$input.all(), ...larges]) {
  for (const p of (r.json?.people || [])) {
    if (p && p.id && !parId.has(p.id)) parId.set(p.id, p);
  }
}

// --- Deja dans l'Annuaire (id Apollo ou email) : pas de doublon entre runs ---
const deja = new Set();
try {
  const rep = $('Lire Annuaire').first().json;
  const src = rep.body ?? rep;
  const vals = Array.isArray(src.values) ? src.values : [];
  const hdr  = (vals[0] || []).map(h => String(h ?? '').trim());
  const iId   = hdr.indexOf('ID_Prospect');
  const iMail = hdr.indexOf('Email');
  for (const row of vals.slice(1)) {
    if (iId   >= 0 && row[iId])   deja.add(String(row[iId]).trim());
    if (iMail >= 0 && row[iMail]) deja.add(String(row[iMail]).trim().toLowerCase());
  }
} catch (e) { /* annuaire vide ou illisible */ }

const retenus = [];
for (const p of parId.values()) {
  if (deja.has(String(p.id))) continue;
  const titre = norm(p.title);
  if (!titre) continue;
  const sen = p.seniority || '';
  const depts = [...(p.departments || []), ...(p.subdepartments || []), ...(p.functions || [])];

  let bloc = null;
  for (const b of BLOCS) {
    let touche = b.titres.some(rx => rx.test(titre));
    if (!touche && b.titresSiDept) {
      touche = b.titresSiDept.regex.some(rx => rx.test(titre))
            && b.titresSiDept.depts.some(d => depts.includes(d));
    }
    if (!touche) continue;
    if (b.exclure && b.exclure.some(rx => rx.test(titre))) continue;
    if (!b.sen.includes(sen)) continue;
    bloc = b;
    break;
  }
  if (!bloc) continue;

  const deptOk = bloc.depts ? bloc.depts.some(d => depts.includes(d)) : true;
  const statutMail = p.email_status || 'unavailable';
  const emailable = OK_EMAIL.includes(statutMail) ? 1 : 0;

  retenus.push({
    id: p.id,
    name: p.name || [p.first_name, p.last_name].filter(Boolean).join(' '),
    title: p.title || '',
    seniority: sen,
    linkedin: p.linkedin_url || '',
    email_status: statutMail,
    emailable,
    bloc: bloc.cle,
    niveau: bloc.niveau,
    score: bloc.poids + (BONUS_SEN[sen] || 0) + (deptOk ? 8 : 0),
  });
}

retenus.sort((a, b) =>
  (b.emailable - a.emailable) || (b.score - a.score) || (a.niveau - b.niveau));

// --- SELECTION ---
// Un contact sans email ET sans LinkedIn n'est d'aucune utilite : ecarte.
const eligibles = retenus.filter(p => p.emailable || p.linkedin);

const parBloc = new Map();
for (const p of eligibles) {
  if (!parBloc.has(p.bloc)) parBloc.set(p.bloc, []);
  parBloc.get(p.bloc).push(p);
}

const NIVEAUX = [1, 2, 3];
const garde = [];
const pris = new Set();
const compteur = {};

// Rotation niveau 1 -> 2 -> 3 : la chaine de decision d'abord, l'approfondissement ensuite.
// respecterQuota=false : plafond par fonction ignore, pour ATTEINDRE MAX coute que coute.
function selectionner(filtre, respecterQuota) {
  let progres = true;
  while (garde.length < MAX && progres) {
    progres = false;
    for (const niv of NIVEAUX) {
      if (garde.length >= MAX) break;
      let choisi = null;
      for (const b of BLOCS) {
        if (b.niveau !== niv) continue;
        if (respecterQuota && (compteur[b.cle] || 0) >= MAX_PAR_FONCTION) continue;
        const c = (parBloc.get(b.cle) || []).find(p => filtre(p) && !pris.has(p.id));
        if (!c) continue;
        if (!choisi || c.score > choisi.score) choisi = c;
      }
      if (choisi) {
        garde.push(choisi);
        pris.add(choisi.id);
        compteur[choisi.bloc] = (compteur[choisi.bloc] || 0) + 1;
        progres = true;
      }
    }
  }
}

const avecEmail = p => p.emailable === 1;
const avecLinkedin = p => p.emailable === 0 && !!p.linkedin;

// 1) emails, plafond par fonction respecte  -> largeur : on couvre les 3 niveaux
// 2) emails restants, plafond ignore        -> on bouche avec les fonctions qui en ont
selectionner(avecEmail, true);
selectionner(avecEmail, false);
const nbAvecEmail = garde.length;

// 3) LinkedIn seuls, meme logique : largeur puis bouchage, pour atteindre MAX
if (INCLURE_SANS_EMAIL && nbAvecEmail < MAX && nbAvecEmail <= SEUIL_COMPLEMENT) {
  selectionner(avecLinkedin, true);
  selectionner(avecLinkedin, false);
}

garde.sort((a, b) => (b.emailable - a.emailable) || (a.niveau - b.niveau) || (b.score - a.score));

const enrichables = garde.filter(p => p.emailable);
const sansEmail   = garde.filter(p => !p.emailable);

const base = {
  _societe: soc._nom_affiche,
  _vus: parId.size,
  _eligibles: eligibles.length,
  _avec_email: enrichables.length,
  _sans_email: sansEmail.length,
  _fonctions: garde.map(p => p.bloc),
  _niveaux: garde.map(p => p.niveau),
};

// --- Aucun contact retenu ---
// On ecrit quand meme UNE ligne dans l'Annuaire, au nom de l'entreprise, pour garder
// la trace du passage : sans ca, une societe sans contact serait invisible et on ne
// saurait pas la distinguer d'une societe jamais traitee.
if (!garde.length) {
  return [{ json: {
    ...base,
    _vide: true,
    _zeroContact: true,
    _nb_a_ecrire: 1,
    details: [], meta: [], metaSansEmail: [],
  }}];
}

const lots = [];
if (enrichables.length) {
  for (let i = 0; i < enrichables.length; i += 10) {
    const tranche = enrichables.slice(i, i + 10);
    lots.push({ json: {
      ...base,
      _vide: false, _zeroContact: false,
      _nb_a_ecrire: tranche.length + (i === 0 ? sansEmail.length : 0),
      details: tranche.map(p => ({ id: p.id })),
      meta: tranche,
      metaSansEmail: i === 0 ? sansEmail : [],
    }});
  }
} else {
  lots.push({ json: {
    ...base,
    _vide: false, _zeroContact: false,
    _nb_a_ecrire: sansEmail.length,
    details: [], meta: [], metaSansEmail: sansEmail,
  }});
}
return lots;

// Construit le bloc de lignes a ajouter dans l'Annuaire, aligne sur les EN-TETES REELS.
// Email_Statut, Action et Score sont laisses VIDES (traites en aval / desactives).
//   Source  = nom de la feuille source        Secteur = secteur reel trouve par l'IA
// Statut : "Nouveau" | "0 contact" (societe sans contact) |
//          "Contact FR non trouve" (aucun contact francais : repli sur des etrangers, max 5).
const soc = $('Parser qualification').first().json;
const aujourdhui = new Date().toISOString().slice(0, 10);

const ECRIRE_SCORE = false;
const TROU_MAX     = 100;
const MAX_ETRANGER = $('Config').first().json.MAX_CONTACTS_ETRANGER ?? 5;

// Repli etranger signale par les filtres de localisation, relaye par "Sonde motif".
let replriEtranger = false;
try { replriEtranger = $('Sonde motif').first().json._fallback_hors_france === true; } catch (e) {}

// ================= GARDE-FOU ANTI-DOUBLON INTRA-RUN =================
// n8n RECOUD les connexions quand on supprime un noeud : un lien direct peut reapparaitre
// par-dessus une branche d'IF et creer un second chemin vers ce mappeur. C'est arrive trois
// fois, dont une sur deux etages -> les memes 10 contacts ecrits 4 fois. On refuse donc
// d'emettre un ID_Prospect deja emis PENDANT CE RUN, quel que soit le cablage.
const dejaEmis = new Set();
for (let r = 0; r < 500; r++) {
  let items;
  try { items = $('Mapper Annuaire').all(0, r); } catch (e) { break; }
  if (!items || !items.length) break;
  for (const it of items) {
    for (const id of ((it.json && it.json._ids) || [])) if (id) dejaEmis.add(String(id));
  }
}

const rep = $('Lire Annuaire').first().json;
const src = rep.body ?? rep;
const vals    = Array.isArray(src.values) ? src.values : [];
const address = String(src.address || '');

const mDeb = address.match(/!\$?([A-Z]+)\$?(\d+)/i);
const colDepart   = mDeb ? mDeb[1].toUpperCase() : 'A';
const ligneDepart = mDeb ? parseInt(mDeb[2], 10) : 1;

// !! usedRange MENT : il inclut les lignes/colonnes seulement MISES EN FORME (observe A1:X10000
// pour ~160 lignes de donnees). On se fie donc au CONTENU.
const enteteBrut = (vals[0] || []).map(h => String(h ?? '').trim());
let nbColonnes = 0;
enteteBrut.forEach((h, i) => { if (h) nbColonnes = i + 1; });
if (!nbColonnes) {
  throw new Error('En-tetes de la feuille Annuaire introuvables (address=' + address + ').');
}
const entetes = enteteBrut.slice(0, nbColonnes);

// Hauteur reelle = fin du bloc RATTACHE a l'en-tete ; les grappes isolees sont ecartees.
const remplies = [];
vals.forEach((r, i) => { if ((r || []).some(c => String(c ?? '').trim() !== '')) remplies.push(i); });
let k = remplies.length - 1;
while (k >= 0) {
  let deb = k;
  while (deb > 0 && remplies[deb] - remplies[deb - 1] <= TROU_MAX) deb--;
  if (deb === 0) break;
  k = deb - 1;
}
const dernierIndex = k >= 0 ? remplies[k] : 0;
let derniereLigne  = ligneDepart + dernierIndex;
const egarees = remplies.filter(i => i > dernierIndex).map(i => ligneDepart + i);

// --- CORRECTION DE DECALAGE INTRA-RUN ---
// "Lire Annuaire" est en executeOnce : son instantane date du DEBUT du run. Sans ca, chaque
// societe de la boucle repartirait de la meme ligne et ecraserait la precedente.
for (let r = 0; r < 500; r++) {
  let items;
  try { items = $('Ecrire Annuaire').all(0, r); } catch (e) { break; }
  if (!items || !items.length) break;
  const rep2 = items[0].json || {};
  const a = String((rep2.body ? rep2.body.address : rep2.address) || '');
  const m = a.match(/:\$?[A-Z]+\$?(\d+)\s*$/i);
  if (m) derniereLigne = Math.max(derniereLigne, parseInt(m[1], 10));
}

const colVersNum = s => [...s].reduce((a, c) => a * 26 + (c.charCodeAt(0) - 64), 0);
const numVersCol = n => { let s = ''; while (n > 0) { const r = (n - 1) % 26; s = String.fromCharCode(65 + r) + s; n = Math.floor((n - 1) / 26); } return s; };

const entreprise    = soc._nom_affiche || soc._nom_recherche || '';
const feuilleSource = soc._sheet || soc._classe || '';
const secteurMetier = (soc._secteur && soc._secteur !== 'NOT_FOUND') ? soc._secteur : '';
const siteWeb       = (soc._site_web && soc._site_web !== 'NOT_FOUND') ? soc._site_web : '';
const STATUT_BASE   = replriEtranger ? 'Contact FR non trouve' : 'Nouveau';

const emailDe = m => {
  const e = (m && m.email) || '';
  return (e && !String(e).includes('email_not_unlocked')) ? e : '';
};

function gabarit() {
  return {
    'ID_Prospect': '', 'Entreprise': entreprise, 'Domaine': '', 'Secteur': secteurMetier,
    'Décideur': '', 'Post': '', 'Email': '', 'Email_Statut': '', 'Linkedin': '',
    'Téléphone': '', 'Statut Téléphone': '', 'Source': feuilleSource,
    'Date_Ajout': aujourdhui, 'Statut': STATUT_BASE, 'Score': '', 'Action': '',
    'Date_J0': '', 'Date_J5': '', 'Date_J12': '', 'Tel_verifie': '', '_idx': '',
  };
}

const prospects = [];
let domaineEntreprise = '';
let domaineMotif = '';
let motifUtilise = '';
let nbDeduits = 0;

const items = $input.all().map(i => i.json || {});
const zeroContact = items.some(j => j._zeroContact === true);

if (zeroContact) {
  // Societe sans aucun contact : une ligne au nom de l'entreprise, pour garder la trace du
  // passage. Sans elle, on ne distinguerait pas une societe sans contact d'une societe jamais
  // traitee.
  const l = gabarit();
  l['ID_Prospect'] = 'AUCUN-' + (soc._siren || (feuilleSource + '-L' + (soc._rowNumber || '')));
  l['Domaine'] = soc._domaine || siteWeb;
  l['Statut'] = '0 contact';
  prospects.push(l);
} else {
  const paires = [];
  for (const j of items) {
    const meta    = j.meta || [];
    const matches = j.matches || [];
    const deduits = j.deduits || [];
    const sans    = j.metaSansEmail || [];

    if (j._domaine_motif && !domaineMotif) domaineMotif = j._domaine_motif;
    if (j._motif) motifUtilise = j._motif;

    const n = Math.max(matches.length, meta.length);
    for (let x = 0; x < n; x++) {
      const m = matches[x] || {};
      const p = meta[x] || {};
      if (!m.id && !p.id) continue;
      paires.push({ m, p });
    }
    for (const p of deduits) {
      if (!p.id) continue;
      nbDeduits++;
      paires.push({ m: { id: p.id, email: p.email }, p });
    }
    for (const p of sans) {
      if (!p.id) continue;
      paires.push({ m: null, p });
    }
  }

  if (!paires.length) {
    throw new Error('Lot non vide mais aucun prospect appariable (societe ' + entreprise + ').');
  }

  // UN SEUL domaine par entreprise, celui de la MESSAGERIE : Apollo renvoie le domaine VITRINE
  // (airfrance.com) alors que les salaries sont en airfrance.fr. Le calcul par frequence evite
  // aussi qu'un groupe issu de fusions (SEKO / Bansard / B2C Trans) affiche trois domaines.
  const freq = {};
  for (const { m } of paires) {
    const e = emailDe(m);
    const d = e.includes('@') ? e.split('@')[1].toLowerCase() : '';
    if (d) freq[d] = (freq[d] || 0) + 1;
  }
  const tri = Object.entries(freq).sort((a, b) => b[1] - a[1]);
  domaineEntreprise = (tri.length && tri[0][0]) || domaineMotif || soc._domaine || siteWeb || '';

  for (const { m, p } of paires) {
    const l = gabarit();
    l['ID_Prospect'] = (m && m.id) || p.id;
    l['Domaine'] = domaineEntreprise;
    l['Décideur'] = (m && m.name) || [m && m.first_name, m && m.last_name].filter(Boolean).join(' ') || p.name || '';
    l['Post'] = (m && m.title) || p.title || '';
    l['Email'] = emailDe(m);
    l['Linkedin'] = (m && m.linkedin_url) || p.linkedin || '';
    l['Score'] = ECRIRE_SCORE ? (soc._score ?? '') : '';
    prospects.push(l);
  }
}

// Repli etranger : plafond de securite. "Sonde motif" a deja limite l'enrichissement, ce slice
// ne fait que garantir le nombre de lignes ecrites.
const plafonnes = (replriEtranger && !zeroContact) ? prospects.slice(0, MAX_ETRANGER) : prospects;

// Garde-fou anti-doublon
const retenus = plafonnes.filter(p => !dejaEmis.has(String(p['ID_Prospect'])));
const ignoresDoublon = plafonnes.length - retenus.length;
if (!retenus.length) return [];

// Alignement souple sur les en-tetes reels : la cle ignore casse, accents, espaces, underscores.
const cle = s => String(s || '').toLowerCase().normalize('NFD')
  .replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]/g, '');

const parCle = {};
entetes.forEach((h, i) => { if (h) parCle[cle(h)] = i; });
const ALIAS = { linkedin: ['linledin', 'linkedin', 'linkedln'] };

function colonneDe(nom) {
  const k2 = cle(nom);
  if (parCle[k2] !== undefined) return parCle[k2];
  const alias = ALIAS[k2];
  if (alias) for (const a of alias) if (parCle[a] !== undefined) return parCle[a];
  return undefined;
}

const inconnues = new Set();
const lignes = retenus.map(p => {
  const row = new Array(nbColonnes).fill('');
  for (const [c1, v] of Object.entries(p)) {
    const c = colonneDe(c1);
    if (c === undefined) { inconnues.add(c1); continue; }
    row[c] = v;
  }
  return row;
});

const debut  = derniereLigne + 1;
const fin    = debut + lignes.length - 1;
const colFin = numVersCol(colVersNum(colDepart) + nbColonnes - 1);

return [{ json: {
  _address: colDepart + debut + ':' + colFin + fin,
  _nb: lignes.length,
  _ids: retenus.map(p => p['ID_Prospect']),
  _fallback_hors_france: replriEtranger,
  _ignores_doublon: ignoresDoublon,
  _zero_contact: zeroContact,
  _domaine: domaineEntreprise,
  _motif: motifUtilise,
  _nb_deduits: nbDeduits,
  _motif_source: items.map(j => j._motif_source).filter(Boolean).join(','),
  _credits_apollo: items.reduce((s, j) => s + (j.matches || []).length, 0),
  _zone_lue: address,
  _derniere_ligne_bloc: derniereLigne,
  _lignes_egarees: egarees,
  _colonnes: nbColonnes,
  _colonnes_non_mappees: [...inconnues],
  values: lignes,
}}];

let prep = [];
try { prep = $('Preparer societes').all(); } catch (e) {}
const p = prep[0]?.json || {};

// Bilan sur TOUTES les iterations de la boucle (all() ne rend que la derniere,
// il faut donc parcourir les runs un par un).
const parClasse = {};
const scores = [];
let coutIaUsd = 0, echecsIa = 0, dureeIaMs = 0, societes = 0;

for (let r = 0; r < 1000; r++) {
  let items;
  try { items = $('Parser qualification').all(0, r); } catch (e) { break; }
  if (!items || !items.length) break;
  const q = items[0].json;
  societes++;
  const k = q._ia_ok ? (q._classification || '?') : 'ECHEC_IA';
  parClasse[k] = (parClasse[k] || 0) + 1;
  if (!q._ia_ok) echecsIa++;
  if (typeof q._score === 'number') scores.push(q._score);
  if (typeof q._ia_cout_usd === 'number') coutIaUsd += q._ia_cout_usd;
  if (typeof q._ia_duree_ms === 'number') dureeIaMs += q._ia_duree_ms;
}

// Lignes reellement ecrites dans l'Annuaire pendant ce run
let lignesEcrites = 0;
for (let r = 0; r < 1000; r++) {
  let items;
  try { items = $('Mapper Annuaire').all(0, r); } catch (e) { break; }
  if (!items || !items.length) break;
  lignesEcrites += items[0].json._nb || 0;
}

const moyenne = scores.length
  ? Math.round((scores.reduce((a, b) => a + b, 0) / scores.length) * 10) / 10
  : null;

return [{ json: {
  societes_traitees_ce_run: societes,
  societes_restantes_apres_filtre: p._candidates_total ?? null,
  lignes_ecrites_annuaire: lignesEcrites,
  lignes_sans_nom_ignorees: p._ignorees ?? 0,
  qualification_par_classe: parClasse,
  score_moyen: moyenne,
  echecs_ia: echecsIa,
  cout_ia_usd_indicatif: Math.round(coutIaUsd * 10000) / 10000,
  duree_ia_totale_s: Math.round(dureeIaMs / 1000),
  fin: new Date().toISOString(),
}}];

const rep = $input.first().json;
const src = rep.body ?? rep;
const feuilles = Array.isArray(src.value) ? src.value : [];
const f = feuilles.find(w => String(w.name || '').trim() === 'Annuaire');
if (!f) {
  throw new Error('Feuille "Annuaire" introuvable. Feuilles du classeur : ' + feuilles.map(w => w.name).join(' | '));
}
return [{ json: { annuaireId: f.id, annuaireNom: f.name } }];

// Construit le prompt de qualification. AUCUNE donnee personnelle n'est envoyee :
// uniquement des donnees d'entreprise (raison sociale, SIREN, NAF, commune).
const soc = $input.first().json;
const cfg = $('Config').first().json;
const SCORING = cfg.IA_SCORING === true;
const SEUIL = cfg.SEUIL_CORE ?? 7;

const l = (label, v) => {
  const s = String(v ?? '').trim();
  return (s && s !== '-') ? label + ' : ' + s : null;
};

const fiche = [
  l('Raison sociale', soc._raison),
  l('Nom commercial', soc._enseigne),
  l('SIREN', soc._siren),
  l('Code NAF', soc._naf),
  l('Commune', soc._commune),
  l('Taille', soc._taille),
  l('Tranche effectif', soc._effectif),
  l('Categorie interne', soc._classe),
  l('Nom retenu par Apollo', soc._org_nom),
  l('Domaine connu', soc._domaine),
].filter(Boolean).join('\n');

// Metiers que acme FOURNIT. Sert de vocabulaire prioritaire, pas de liste fermee :
// une liste fermee renvoyait NOT_FOUND sur toute compagnie aerienne (Air Corsica, Air Austral)
// et forcait de faux choix sur les autres (Singapore Airlines classee "escale").
const SECTEURS = [
  '  handling   assistance en escale, piste, bagages, avitaillement',
  '  surete     surete ou securite aeroportuaire, controle, filtrage',
  '  catering   restauration aerienne, commissariat de bord',
  '  fret       fret aerien, cargo, transitaire, logistique aeroportuaire',
  '  escale     operations d escale, coordination avion, agent de trafic',
  '  accueil    accueil passagers, agent d accueil, service en aerogare',
  '  pmr        assistance aux personnes a mobilite reduite',
  '  nettoyage  nettoyage ou proprete (cabine, aerogare, locaux)',
].join('\n');

let prompt;

if (!SCORING) {
  // --- Mode SECTEUR SEUL ---
  // On veut le secteur REEL de l'entreprise, pas le metier qu'elle achete a acme.
  prompt = [
    'Tu identifies le SECTEUR D ACTIVITE REEL d une entreprise, pour acme INTERIM,',
    'agence de travail temporaire specialisee dans les metiers aeroportuaires en',
    'Ile-de-France (Roissy CDG, Orly, Le Bourget).',
    '',
    'ENTREPRISE',
    fiche,
    '',
    'Si l entreprise exerce l un des metiers ci-dessous, emploie EXACTEMENT ce mot-cle :',
    SECTEURS,
    '',
    'Sinon, donne son secteur reel en 1 a 3 mots, en francais et en minuscules.',
    'Exemples : compagnie aerienne, transitaire, organisme de formation, travail temporaire,',
    'maintenance aeronautique, hotellerie, restauration, transport routier.',
    'Ne reponds NOT_FOUND que si tu ne connais vraiment pas cette entreprise. N invente pas.',
    '',
    'REPONSE : un seul objet JSON strict. AUCUN texte autour, AUCUN bloc de code markdown.',
    '{"secteur":"compagnie aerienne","site_web":"exemple.fr"}',
    '',
    '"site_web" : le domaine principal si tu le connais avec certitude, sinon NOT_FOUND.',
  ].join('\n');
} else {
  // --- Mode COMPLET : secteur + classification + score ---
  prompt = [
    'Tu qualifies une entreprise pour acme INTERIM, agence de travail temporaire specialisee',
    'dans les metiers AEROPORTUAIRES en Ile-de-France (Roissy CDG, Orly, Le Bourget).',
    'acme fournit du personnel OPERATIONNEL : piste, bagagiste, agent d escale, accueil, PMR,',
    'surete, catering, fret, nettoyage.',
    '',
    'ENTREPRISE A QUALIFIER',
    fiche,
    '',
    'ETAPE 1 - CLASSIFICATION (etiquette informative, elle ne bloque rien)',
    '  CORE = coeur de cible commerciale, score >= ' + SEUIL,
    '  EDGE = cible peripherique exploitable, score < ' + SEUIL,
    '  OUT  = hors cible commerciale. Donne alors la valeur EXACTE ci-dessous dans "raison" :',
    '    ETT_concurrente | compagnie_aerienne | organisme_formation | hors_aero |',
    '    logistique_non_aero | poste_bureau | support_non_operationnel |',
    '    poste_mixte_non_clair | entreprise_non_identifiable',
    '',
    'ETAPE 2 - SCORING - additif, sur 10, TOUJOURS renseigne (meme si OUT)',
    '  +4  entreprise aviation confirmee   +3  metier terrain',
    '  +2  CDG / Orly / Le Bourget         +1  contrat court / interim',
    '',
    'ETAPE 3 - SECTEUR reel de l entreprise.',
    'Si elle exerce l un des metiers ci-dessous, emploie EXACTEMENT ce mot-cle :',
    SECTEURS,
    'Sinon, donne son secteur reel en 1 a 3 mots, en francais et en minuscules',
    '(ex : compagnie aerienne, transitaire, organisme de formation).',
    '',
    'REPONSE : un seul objet JSON strict. AUCUN texte autour, AUCUN bloc de code markdown.',
    '{"pertinent":true,"raison":"explication courte","secteur":"handling","score":8,"classification":"CORE","site_web":"exemple.fr"}',
    '',
    '"pertinent" : false uniquement quand la classification est OUT.',
    '"site_web"  : le domaine principal si tu le connais avec certitude, sinon NOT_FOUND. N invente pas.',
  ].join('\n');
}

return [{ json: { ...soc, prompt } }];

// Appel du CLI Claude Code embarque dans l'image n8n-custom, via le wrapper claude-run.
//
// CONTRAINTE STRUCTURANTE (ne pas contourner) : le jeton est un FICHIER
// (/run/claude/token), relu par le wrapper A CHAQUE APPEL, dans le process fils.
// Le task runner n8n filtre l'environnement a 13 variables et bloque process.env :
// ce noeud ne peut PAS lire le jeton, et ne doit pas essayer.
// Changer de compte = reecrire /opt/n8n/secrets/claude/token cote hote (dossier monte).
const cfg = $('Config').first().json;
const debut = Date.now();

// --- Interrupteur : qualification IA desactivee ---
if (cfg.QUALIFICATION_IA === false) {
  return [{ json: {
    desactive: true,
    sortie: '', sortieErreur: null, erreur: null, codeSortie: 0,
    dureeAppelMs: 0, rang: null, quotaEpuise: false, messageApi: null,
  }}];
}

const mod = require('child_process');
const prompt = String($input.first().json.prompt || '');

let sortie = '';
let sortieErreur = null;
let erreur = null;
let codeSortie = 0;

try {
  // execFileSync : arguments en TABLEAU, sans shell -> aucune injection possible.
  sortie = String(mod.execFileSync(
    'claude-run',
    ['-p', prompt, '--output-format', 'json', '--model', cfg.MODELE_IA || 'sonnet'],
    { encoding: 'utf8', timeout: cfg.TIMEOUT_IA_MS || 270000, maxBuffer: 33554432, cwd: '/tmp' }
  ));
} catch (err) {
  codeSortie = (err && typeof err.status === 'number') ? err.status : -1;
  erreur = String((err && err.message) || err).slice(0, 400);
  sortie = (err && err.stdout) ? String(err.stdout) : '';
  sortieErreur = (err && err.stderr) ? String(err.stderr).slice(0, 3000) : null;
}

// Le wrapper annonce le compte utilise sur stderr : "rang=abonnement" ou "rang=api".
const mRang = /rang=(\w+)/.exec(sortieErreur || '');

// Diagnostic quota : le CLI renvoie du JSON meme en erreur.
let quotaEpuise = false;
let messageApi = null;
const i = sortie.indexOf('{');
if (i >= 0) {
  try {
    const env = JSON.parse(sortie.slice(i, sortie.lastIndexOf('}') + 1));
    messageApi = env.result ? String(env.result).slice(0, 200) : null;
    quotaEpuise = env.api_error_status === 429;
  } catch (e) { /* sortie illisible */ }
}
if (quotaEpuise) {
  erreur = 'QUOTA EPUISE sur le compte actif' + (messageApi ? ' -- ' + messageApi : '')
    + ' | Basculer : cp /opt/n8n/secrets/claude-comptes/<compte>.token'
    + ' /opt/n8n/secrets/claude/token && chown 1000:1000 ... && chmod 400 ...';
}

return [{ json: {
  desactive: false,
  sortie, sortieErreur, erreur, codeSortie,
  dureeAppelMs: Date.now() - debut,
  rang: mRang ? mRang[1] : null,
  quotaEpuise, messageApi,
} }];

// Deballe la sortie du CLI puis le JSON metier, et VALIDE chaque champ.
// Le wrapper claude-run imprime une ligne "rang=..." avant le JSON : pas de JSON.parse
// direct possible, il faut isoler le premier objet.
const cfg = $('Config').first().json;
const SCORING = cfg.IA_SCORING === true;
const soc = $('Choisir societe').first().json;
const r = $input.first().json;

const SECTEURS = ['handling','surete','catering','fret','escale','accueil','pmr','nettoyage'];
const RAISONS_OUT = ['ETT_concurrente','poste_bureau','hors_aero','compagnie_aerienne',
  'logistique_non_aero','support_non_operationnel','poste_mixte_non_clair',
  'entreprise_non_identifiable','organisme_formation'];

const statutBase = () => (soc._match ? 'TRUE' : 'NO_MATCH');

// --- Qualification IA desactivee : passage en neutre ---
if (r.desactive === true) {
  return [{ json: {
    ...soc,
    _pertinent: true, _classification: '', _score: null,
    _secteur: 'NOT_FOUND', _raison: '', _site_web: 'NOT_FOUND',
    _apollo_statut: statutBase(),
    _ia_ok: true, _ia_desactivee: true, _ia_diag: null,
    _ia_cout_usd: null, _ia_duree_ms: 0,
  }}];
}

function premierObjetJson(txt) {
  const s = String(txt ?? '');
  const i = s.indexOf('{');
  const j = s.lastIndexOf('}');
  if (i < 0 || j <= i) return null;
  try { return JSON.parse(s.slice(i, j + 1)); } catch (e) { return null; }
}

let qualif = null;
let diag = r.erreur || null;
let coutUsd = null;

const enveloppe = premierObjetJson(r.sortie);
if (enveloppe) {
  coutUsd = enveloppe.total_cost_usd ?? null;
  if (enveloppe.is_error) diag = diag || 'CLI is_error';
  const texte = enveloppe.result ?? enveloppe.text ?? enveloppe.content ?? '';
  qualif = premierObjetJson(typeof texte === 'string' ? texte : JSON.stringify(texte));
  if (!qualif && (enveloppe.secteur !== undefined || enveloppe.pertinent !== undefined)) qualif = enveloppe;
}
if (!qualif) {
  diag = diag || ('reponse IA illisible : ' + String(r.sortie || r.sortieErreur || '(vide)').slice(0, 300));
}

// --- Champs communs aux deux modes ---
// Le secteur est du TEXTE LIBRE court. L'ancienne validation le forcait a appartenir aux 8
// metiers acme, ce qui renvoyait NOT_FOUND sur toute compagnie aerienne (Air Corsica,
// Air Austral) : la colonne restait vide sur des societes parfaitement identifiees.
// On garde les 8 mots-cles comme vocabulaire prioritaire cote prompt, sans les imposer ici.
let secteur = 'NOT_FOUND', siteWeb = 'NOT_FOUND';
if (qualif) {
  secteur = String(qualif.secteur || '').toLowerCase().trim()
    .replace(/["'`\r\n]/g, ' ').replace(/\s+/g, ' ').slice(0, 40);
  // Une phrase n'est pas un secteur : au-dela de 4 mots, l'IA a mal repondu.
  if (!secteur || secteur === 'not_found' || secteur.split(' ').length > 4) secteur = 'NOT_FOUND';
  siteWeb = String(qualif.site_web || 'NOT_FOUND').trim();
}

// --- Mode SECTEUR SEUL : ni score ni classification ---
if (!SCORING) {
  return [{ json: {
    ...soc,
    _pertinent: true, _classification: '', _score: null,
    _secteur: secteur, _raison: '', _site_web: siteWeb,
    // chaine vide si l'IA a echoue -> societe non marquee, reprise au prochain run
    _apollo_statut: qualif ? statutBase() : '',
    _ia_ok: !!qualif, _ia_desactivee: false, _ia_diag: diag,
    _ia_cout_usd: coutUsd, _ia_duree_ms: r.dureeAppelMs ?? null,
  }}];
}

// --- Mode COMPLET ---
let pertinent = false, classification = 'OUT', score = 0, raison = '';
if (qualif) {
  pertinent = qualif.pertinent === true;
  classification = String(qualif.classification || (pertinent ? 'EDGE' : 'OUT')).toUpperCase().trim();
  if (!['CORE','EDGE','OUT'].includes(classification)) classification = pertinent ? 'EDGE' : 'OUT';
  if (classification === 'OUT') pertinent = false;

  score = Number(qualif.score);
  if (!Number.isFinite(score)) score = 0;
  score = Math.max(0, Math.min(10, Math.round(score)));

  raison = String(qualif.raison || '').slice(0, 200);
  if (!pertinent && !RAISONS_OUT.includes(raison)) diag = diag || ('raison hors liste : ' + raison);
}

let statut = '';
if (qualif) {
  statut = classification + ' ' + score + '/10';
  if (classification === 'OUT' && raison) statut += ' ' + raison;
}

return [{ json: {
  ...soc,
  _pertinent: pertinent, _classification: classification, _score: score,
  _secteur: secteur, _raison: raison, _site_web: siteWeb,
  _apollo_statut: statut,
  _ia_ok: !!qualif, _ia_desactivee: false, _ia_diag: diag,
  _ia_cout_usd: coutUsd, _ia_duree_ms: r.dureeAppelMs ?? null,
}}];

// Deduit le MOTIF d'adresse email de l'entreprise a partir des SONDES : les seuls contacts
// reellement enrichis. But : reconstituer les autres adresses sans racheter de credits Apollo.
//
// MOTEUR PARAMETRIQUE. On n'a plus une liste fermee de gabarits mais un espace de RECETTES
// explore exhaustivement : ordre (prenom/nom, nom/prenom, prenom seul, nom seul) x troncature
// (mot entier ou 1 a 4 lettres) x separateur ('' . - _) x style du prenom x style du nom.
// 10 000 combinaisons testees par sonde, en moins d'une milliseconde. Mesure sur les adresses
// reelles d'Air France : 16/16 reproduites, contre 10/16 avec l'ancienne liste de 16 gabarits.
//
// REGLE DE SECURITE : une recette n'est retenue que si elle reproduit TOUTES les sondes, au
// caractere pres. C'est une INTERSECTION, pas un vote. Air France melange laurent.bourianne@,
// thlaousse@ et auboutillier@ : intersection vide, donc aucune deduction et repli payant.
// Mieux vaut payer que remplir l'Annuaire d'adresses fausses.
//
// !! Le moteur doit rester IDENTIQUE a celui de "Parser motif" : ici on detecte, la-bas on rend.
const cfg = $('Config').first().json;
const MOTIF_IA = cfg.MOTIF_IA ?? false;

const lot = $('Sonde motif').first().json;
const rep = $input.first().json;
const src = rep.body ?? rep;

const matches = src.matches || [];
const meta    = lot.meta || [];

const passe = {
  matches: matches,
  meta: meta,
  metaSansEmail: lot.metaSansEmail || [],
  aDeduire: lot.aDeduire || [],
  detailsReste: lot.detailsReste || [],
  _zeroContact: lot._zeroContact === true,
  _societe: lot._societe || '',
  _mode: lot._mode || 'complet',
};

// Normalisation FR : accents retires, apostrophes supprimees, prenoms composes et particules
// eclates en mots. "Jose-Marie D'Aubigne" -> ['jose','marie','daubigne']
function mots(s) {
  const b = String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '')
    .toLowerCase().replace(/['’]/g, '')
    .replace(/[^a-z0-9\s-]/g, ' ').replace(/\s+/g, ' ').trim();
  return b.split(/[\s-]+/).filter(Boolean);
}
function styles(s) {
  const m = mots(s);
  if (!m.length) return null;
  return { traitUnion: m.join('-'), colle: m.join(''), point: m.join('.'),
           premier: m[0], dernier: m[m.length - 1] };
}

const STY   = ['traitUnion', 'colle', 'point', 'premier', 'dernier'];
const SEP   = ['', '.', '-', '_'];
const COUPE = [0, 1, 2, 3, 4];            // 0 = mot entier
const ORDRE = ['pn', 'np', 'p', 'n'];

function rendre(r, sp, sn) {
  const a = sp[r.sp], b = sn[r.sn];
  if (!a || !b) return null;
  const ca = r.cp ? a.slice(0, r.cp) : a;
  const cb = r.cn ? b.slice(0, r.cn) : b;
  if (r.ordre === 'p') return ca;
  if (r.ordre === 'n') return cb;
  return r.ordre === 'pn' ? ca + r.sep + cb : cb + r.sep + ca;
}
function cle(r) { return [r.ordre, r.cp, r.cn, r.sep, r.sp, r.sn].join('|'); }

function recettes(mail, pre, nom) {
  const sp = styles(pre), sn = styles(nom);
  const set = new Set();
  if (!sp || !sn) return set;
  // Un suffixe numerique (flgarcia1) departage deux homonymes : il n'est PAS generalisable.
  // On l'ecarte pour inferer la regle, et on ne le remet JAMAIS a la deduction.
  const loc = mail.split('@')[0].replace(/\d+$/, '');
  if (!loc) return set;
  for (const ordre of ORDRE) for (const cp of COUPE) for (const cn of COUPE)
    for (const sep of SEP) for (const a of STY) for (const b of STY) {
      const r = { ordre, cp, cn, sep, sp: a, sn: b };
      if (rendre(r, sp, sn) === loc) set.add(cle(r));
    }
  return set;
}

// --- Intersection sur toutes les sondes ---
let inter = null;
let domaine = '';
const sondesVues = [];
const nonReconnues = [];

for (let i = 0; i < Math.max(matches.length, meta.length); i++) {
  const m = matches[i] || {};
  const p = meta[i] || {};
  const brut = String(m.email || '');
  const mail = (brut && brut.indexOf('email_not_unlocked') === -1) ? brut.toLowerCase() : '';
  if (!mail) continue;

  const pre = m.first_name || p.first_name || '';
  const nm  = m.last_name  || p.last_name  || '';
  if (!domaine) domaine = mail.split('@')[1];

  const t = recettes(mail, pre, nm);
  sondesVues.push(mail + ' (' + t.size + ')');
  // Une adresse qu'AUCUNE recette ne reproduit signale presque toujours un ecart de NOM
  // (surnom, nom d'epouse, translitteration), pas une regle exotique : l'espace parametrique
  // couvre deja toutes les regles de chaine plausibles. C'est la seule chose que l'IA peut
  // encore apporter ici.
  if (!t.size) nonReconnues.push({ mail: mail, prenom: pre, nom: nm });
  inter = (inter === null) ? t : new Set([...inter].filter(x => t.has(x)));
}

const triples = inter ? [...inter] : [];

const commun = Object.assign({}, passe, {
  _domaine_motif: domaine,
  _sondes: sondesVues,
  _nb_sondes_lues: sondesVues.length,
  _non_reconnues: nonReconnues.map(x => x.mail),
});

// Cas 1 : une recette commune reproduit toutes les sondes -> aucun appel IA necessaire.
if (triples.length) {
  return [{ json: Object.assign({}, commun, {
    _skipIA: true, _motif_source: 'parametrique', _triples: triples, prompt: '',
  })}];
}

// Cas 2 : IA coupee, ou rien a corriger -> repli payant.
if (!MOTIF_IA || !nonReconnues.length) {
  return [{ json: Object.assign({}, commun, {
    _skipIA: true, _motif_source: 'aucun', _triples: [], prompt: '',
  })}];
}

// Cas 3 : on demande a l'IA le VRAI nom encode dans l'adresse. Elle ne propose jamais
// d'adresse ni de regle : le code relance ensuite la recherche parametrique avec les noms
// corriges et n'accepte le resultat que s'il reproduit toutes les sondes.
const prompt = [
  "Des adresses email professionnelles ne correspondent pas au nom connu de la personne.",
  'Cause habituelle : diminutif, nom de naissance ou nom d\'epouse, translitteration, second prenom.',
  '',
  nonReconnues.map(x =>
    '  adresse: ' + x.mail + '   nom connu: ' + x.prenom + ' ' + x.nom).join('\n'),
  '',
  "Pour chaque adresse, donne le prenom et le nom REELLEMENT encodes dans la partie avant le @.",
  "Si l'adresse ne contient visiblement ni prenom ni nom (boite generique, matricule), mets null.",
  '',
  'Reponds UNIQUEMENT par un objet JSON, sans texte autour :',
  '{"corrections":[{"adresse":"...","prenom":"...","nom":"..."}]}',
].join('\n');

return [{ json: Object.assign({}, commun, {
  _skipIA: false, _motif_source: 'ia', _triples: [], prompt: prompt,
  _a_corriger: nonReconnues,
})}];

// Meme mecanique que "Qualification IA" : execFileSync sur le wrapper /usr/local/bin/claude-run,
// arguments en TABLEAU (pas de shell, donc aucune injection possible), timeout sous les 300 s du
// task runner. Le jeton est lu par le wrapper dans /run/claude/token, dans le process FILS :
// il n'est jamais visible ici, et process.env est de toute facon bloque dans le sandbox.
const mod = require('child_process');
const entree = $input.first().json;

// Court-circuit : le gabarit a deja ete trouve de facon deterministe, ou l'IA est coupee.
// On ne depense ni quota ni les ~17 s d'appel pour rien.
if (entree._skipIA === true || !entree.prompt) {
  return [{ json: Object.assign({}, entree, {
    sortie: '', sortieErreur: null, erreur: null, codeSortie: 0, dureeAppelMs: 0,
  })}];
}

const cfg = $('Config').first().json;
const modele = cfg.MODELE_IA || 'sonnet';
const delai  = cfg.TIMEOUT_IA_MS || 270000;
const debut  = Date.now();

let sortie = '';
let sortieErreur = null;
let erreur = null;
let codeSortie = 0;

try {
  sortie = String(mod.execFileSync(
    'claude-run',
    ['-p', entree.prompt, '--output-format', 'json', '--model', modele],
    { encoding: 'utf8', timeout: delai, maxBuffer: 33554432, cwd: '/tmp' }
  ));
} catch (err) {
  codeSortie = (err && typeof err.status === 'number') ? err.status : -1;
  erreur = String((err && err.message) || err).slice(0, 400);
  sortie = (err && err.stdout) ? String(err.stdout) : '';
  sortieErreur = (err && err.stderr) ? String(err.stderr).slice(0, 3000) : null;
}

// On reinjecte la charge utile : sans ca, le parseur en aval perdrait les contacts a deduire.
return [{ json: Object.assign({}, entree, {
  sortie: sortie,
  sortieErreur: sortieErreur,
  erreur: erreur,
  codeSortie: codeSortie,
  dureeAppelMs: Date.now() - debut,
})}];

// Applique la recette retenue aux contacts NON enrichis : une adresse par contact, construite
// depuis leurs prenom/nom reels + le domaine des sondes. Rien n'est invente : sans recette sure,
// on ne fabrique aucune adresse et on bascule sur le repli payant.
//
// !! Le moteur doit rester IDENTIQUE a celui de "Prompt motif" : la-bas on detecte, ici on rend.
const entree   = $input.first().json;
const aDeduire = entree.aDeduire || [];
const domaine  = entree._domaine_motif || '';

function mots(s) {
  const b = String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '')
    .toLowerCase().replace(/['’]/g, '')
    .replace(/[^a-z0-9\s-]/g, ' ').replace(/\s+/g, ' ').trim();
  return b.split(/[\s-]+/).filter(Boolean);
}
function styles(s) {
  const m = mots(s);
  if (!m.length) return null;
  return { traitUnion: m.join('-'), colle: m.join(''), point: m.join('.'),
           premier: m[0], dernier: m[m.length - 1] };
}
const STY   = ['traitUnion', 'colle', 'point', 'premier', 'dernier'];
const SEP   = ['', '.', '-', '_'];
const COUPE = [0, 1, 2, 3, 4];
const ORDRE = ['pn', 'np', 'p', 'n'];

function rendre(r, sp, sn) {
  const a = sp[r.sp], b = sn[r.sn];
  if (!a || !b) return null;
  const ca = r.cp ? a.slice(0, r.cp) : a;
  const cb = r.cn ? b.slice(0, r.cn) : b;
  if (r.ordre === 'p') return ca;
  if (r.ordre === 'n') return cb;
  return r.ordre === 'pn' ? ca + r.sep + cb : cb + r.sep + ca;
}
function cle(r) { return [r.ordre, r.cp, r.cn, r.sep, r.sp, r.sn].join('|'); }
function depuisCle(k) {
  const c = k.split('|');
  return { ordre: c[0], cp: +c[1], cn: +c[2], sep: c[3], sp: c[4], sn: c[5] };
}
function recettes(mail, pre, nom) {
  const sp = styles(pre), sn = styles(nom);
  const set = new Set();
  if (!sp || !sn) return set;
  const loc = String(mail).split('@')[0].replace(/\d+$/, '');
  if (!loc) return set;
  for (const ordre of ORDRE) for (const cp of COUPE) for (const cn of COUPE)
    for (const sep of SEP) for (const a of STY) for (const b of STY) {
      const r = { ordre, cp, cn, sep, sp: a, sn: b };
      if (rendre(r, sp, sn) === loc) set.add(cle(r));
    }
  return set;
}

let triples = entree._triples || [];
let source  = entree._motif_source || 'aucun';

// --- Reponse IA : des NOMS corriges, jamais une adresse ni une regle ---
// L'IA a seulement pu dire "cette adresse encode en realite tel prenom / tel nom". On relance
// la recherche parametrique avec ces noms et on ne garde le resultat que s'il reproduit
// TOUTES les sondes. Une hallucination ne peut donc pas produire d'adresse : elle echoue au
// controle et on repart au repli payant.
if (!triples.length && entree._skipIA === false) {
  source = 'aucun';
  try {
    const env = JSON.parse(entree.sortie || '{}');
    const txt = String(env.result || '');
    const d = txt.indexOf('{');
    const f = txt.lastIndexOf('}');
    if (d >= 0 && f > d) {
      const o = JSON.parse(txt.slice(d, f + 1));
      const corr = {};
      for (const c of (o.corrections || [])) {
        if (c && c.adresse && c.prenom && c.nom) {
          corr[String(c.adresse).toLowerCase()] = { prenom: c.prenom, nom: c.nom };
        }
      }
      if (Object.keys(corr).length) {
        const matches = entree.matches || [];
        const meta    = entree.meta || [];
        let inter = null;
        for (let i = 0; i < Math.max(matches.length, meta.length); i++) {
          const m = matches[i] || {};
          const p = meta[i] || {};
          const brut = String(m.email || '');
          if (!brut || brut.indexOf('email_not_unlocked') !== -1) continue;
          const mail = brut.toLowerCase();
          const fix = corr[mail];
          const pre = fix ? fix.prenom : (m.first_name || p.first_name || '');
          const nm  = fix ? fix.nom    : (m.last_name  || p.last_name  || '');
          const t = recettes(mail, pre, nm);
          inter = (inter === null) ? t : new Set([...inter].filter(x => t.has(x)));
        }
        if (inter && inter.size) { triples = [...inter]; source = 'ia_noms'; }
      }
    }
  } catch (e) { /* 429, sortie tronquee, JSON casse : on reste en 'aucun' */ }
}

const deduits   = [];
const sansMotif = [];

if (triples.length && domaine) {
  for (const p of aDeduire) {
    const sp = styles(p.first_name);
    const sn = styles(p.last_name);
    if (!sp || !sn) { sansMotif.push(p); continue; }
    // Plusieurs recettes peuvent reproduire les sondes : sur des noms simples, "colle" et
    // "premier" donnent le meme resultat, l'ambiguite est invisible. Elle se revele sur un nom
    // COMPOSE. On n'ecrit donc l'adresse que si TOUTES les recettes convergent sur CE contact.
    const rendus = new Set();
    for (const k of triples) {
      const v = rendre(depuisCle(k), sp, sn);
      if (v) rendus.add(v);
    }
    if (rendus.size === 1) {
      deduits.push(Object.assign({}, p, { email: Array.from(rendus)[0] + '@' + domaine }));
    } else {
      sansMotif.push(p);
    }
  }
} else {
  for (const p of aDeduire) sansMotif.push(p);
}

// Repli : ce qu'on n'a pas su deduire, on le repaie en credits Apollo plutot que de le perdre.
const REPLI = ($('Config').first().json.MOTIF_REPLI_CREDITS ?? true) === true;
const besoinReste = REPLI && sansMotif.length > 0;

// Sans repli, ces contacts partent quand meme dans l'Annuaire, avec leur LinkedIn mais sans email.
const metaSansEmail = besoinReste
  ? (entree.metaSansEmail || [])
  : (entree.metaSansEmail || []).concat(sansMotif);

return [{ json: Object.assign({}, entree, {
  _motif_source: source,
  _motif: triples.length ? triples[0] : '',
  _recettes_retenues: triples.length,
  deduits: deduits,
  _nb_deduits: deduits.length,
  _sans_motif: sansMotif.map(p => p.name),
  metaSansEmail: metaSansEmail,
  aDeduire: sansMotif,
  detailsReste: sansMotif.map(p => ({ id: p.id })),
  _besoin_reste: besoinReste,
})}];

// Repli assume : le gabarit n'a pas pu etre etabli, on a donc REPAYE des credits Apollo pour
// les contacts concernes. On refusionne ces enrichissements avec ceux de la sonde pour que le
// mappeur ne voie qu'une seule liste, identique a celle du mode complet.
const parser = $('Parser motif').first().json;
const rep = $input.first().json;
const src = rep.body ?? rep;

return [{ json: Object.assign({}, parser, {
  matches: (parser.matches || []).concat(src.matches || []),
  meta:    (parser.meta || []).concat(parser.aDeduire || []),
  deduits: parser.deduits || [],
  _credits_replies: (src.matches || []).length,
  _motif_source: (parser._motif_source || 'aucun') + '+repli_credits',
})}];

// BASCULE "quelques sondes au lieu de 10 enrichissements".
// Apollo facture 1 credit par email revele. Mais la recherche de personnes est GRATUITE et
// annonce deja qu'un email valide existe (email_status) : seule la chaine est masquee. On en
// achete donc quelques-unes, on en deduit le gabarit maison, et on reconstruit les autres.
//
// POURQUOI 3 SONDES ET PAS 1 : releve reel sur Air France, une seule entreprise melange
//   warrhalimata@   huguette.pallen@   p.garcia@   bmartins@   thlaousse@
// soit au moins 4 gabarits. Avec une sonde unique on generaliserait le gabarit de cette sonde a
// tout le monde et on ecrirait des adresses fausses (6 sur 6 lors du test). Avec 3 sondes on ne
// retient qu'un gabarit qui les reproduit TOUTES : sur une boite heterogene l'intersection est
// vide, donc on ne deduit rien et on repaie les credits.
const cfg = $('Config').first().json;
const MODE_MOTIF = cfg.MODE_MOTIF ?? true;   // MODE_MOTIF: false dans Config = enrichissement complet
const NB_SONDES  = Math.max(1, cfg.NB_SONDES ?? 3);
const MAX_ETRANGER = Math.max(1, cfg.MAX_CONTACTS_ETRANGER ?? 5);

// --- Repli etranger ? ---
// Les filtres de localisation signalent quand une societe n'a AUCUN contact francais ni sans
// pays, et qu'ils ont donc bascule sur des etrangers. Dans ce cas on plafonne a 5 contacts, et
// on le fait ICI, AVANT l'enrichissement : plafonner a l'ecriture ferait payer des credits pour
// des lignes jetees.
let replriEtranger = false;
function voirRepli(nom) {
  for (let r = 0; r < 50; r++) {
    let items;
    try { items = $(nom).all(0, r); } catch (e) { break; }
    if (!items || !items.length) break;
    for (const it of items) if (it.json && it.json._fallback_hors_france === true) replriEtranger = true;
  }
}
try { voirRepli('Apollo - Personnes'); } catch (e) {}
try { voirRepli('Filtre localisation ciblees'); } catch (e) {}

// "Classer prospects" ne conserve pas first_name / last_name, or le gabarit se detecte sur le
// prenom ET le nom separes. On les recupere dans la reponse BRUTE de la recherche de personnes,
// qui n'a rien coute, indexee par id Apollo.
const nomsParId = new Map();
function avaler(nom) {
  for (let r = 0; r < 50; r++) {
    let items;
    try { items = $(nom).all(0, r); } catch (e) { break; }
    if (!items || !items.length) break;
    for (const it of items) {
      const src = (it.json && it.json.body) ? it.json.body : (it.json || {});
      for (const p of (src.people || [])) {
        if (p && p.id) nomsParId.set(p.id, {
          first_name: p.first_name || '', last_name: p.last_name || '',
        });
      }
    }
  }
}
try { avaler('Apollo - Personnes'); } catch (e) { /* noeud non execute */ }
try { avaler('Apollo - Personnes ciblees'); } catch (e) { /* branche non empruntee */ }

function garnir(p) {
  const n = nomsParId.get(p.id);
  if (n && n.first_name && n.last_name) return Object.assign({}, p, n);
  // Repli : on coupe le nom complet au premier espace. Imparfait sur les prenoms composes,
  // d'ou la preference pour la reponse Apollo quand elle est disponible.
  const t = String(p.name || '').trim().split(/\s+/);
  return Object.assign({}, p, {
    first_name: (n && n.first_name) || t[0] || '',
    last_name:  (n && n.last_name)  || t.slice(1).join(' '),
  });
}

return $input.all().map(item => {
  const lot = item.json || {};
  let meta = (lot.meta || []).map(garnir);
  let sans = lot.metaSansEmail || [];

  // Plafond du repli etranger : 5 contacts au total, emails d'abord.
  if (replriEtranger) {
    meta = meta.slice(0, MAX_ETRANGER);
    sans = sans.slice(0, Math.max(0, MAX_ETRANGER - meta.length));
  }

  const details = replriEtranger ? meta.map(p => ({ id: p.id })) : (lot.details || []);

  const complet = Object.assign({}, lot, {
    meta: meta, metaSansEmail: sans, details: details,
    aDeduire: [], detailsReste: [], _mode: 'complet', _economie_credits: 0,
    _fallback_hors_france: replriEtranger,
    _nb_a_ecrire: (meta.length + sans.length) || lot._nb_a_ecrire,
  });

  if (!MODE_MOTIF || details.length <= NB_SONDES) return { json: complet };

  // Une sonde doit avoir un prenom ET un nom exploitables : sans eux, aucun gabarit n'est
  // detectable et on aurait paye un credit pour rien.
  const idx = [];
  meta.forEach((p, k) => { if (idx.length < NB_SONDES && p.first_name && p.last_name) idx.push(k); });
  if (!idx.length) return { json: complet };

  const sondes = idx.map(k => meta[k]);
  const reste  = meta.filter((_, k) => idx.indexOf(k) === -1);
  if (!reste.length) return { json: complet };

  return { json: Object.assign({}, lot, {
    _mode: 'motif',
    _nb_sondes: sondes.length,
    _fallback_hors_france: replriEtranger,
    details: sondes.map(p => ({ id: p.id })),
    meta: sondes,
    metaSansEmail: sans,
    aDeduire: reste,
    detailsReste: reste.map(p => ({ id: p.id })),
    _economie_credits: reste.length,
    _nb_a_ecrire: meta.length + sans.length,
  })};
});

// RATTRAPAGE SUR ECHEC UNIQUEMENT.
// Les feuilles portent la raison sociale du registre, Apollo indexe les noms COMMERCIAUX.
// Le nettoyage deterministe (retrait de la forme juridique, dans "Preparer societes") suffit
// dans la plupart des cas. Ce noeud ne tourne que sur ce qu'il n'a pas su rattraper : appeler
// l'IA sur les 972 societes couterait environ 4 h 30 de CLI, pour l'essentiel inutilement.
const soc = $input.first().json;

const prompt = [
  "Tu identifies le NOM COMMERCIAL d'une entreprise francaise pour une recherche en base B2B.",
  '',
  'Raison sociale au registre : ' + (soc._raison || soc._nom_brut || ''),
  soc._enseigne ? 'Enseigne declaree : ' + soc._enseigne : '',
  soc._naf      ? 'Code NAF : ' + soc._naf : '',
  soc._commune  ? 'Commune : ' + soc._commune : '',
  soc._classe   ? 'Secteur : ' + soc._classe : '',
  '',
  'La recherche sur "' + (soc._nom_recherche || '') + '" n a donne aucun resultat exploitable.',
  soc._candidats ? 'Resultats approchants renvoyes : ' + soc._candidats
                 : 'Aucun resultat approchant renvoye.',
  '',
  "Donne le nom sous lequel cette entreprise est connue commercialement (marque ou nom d'usage),",
  'sans forme juridique, sans nom de departement ni de filiale.',
  "N'invente rien : si tu ne connais pas cette entreprise, reponds AUCUN. Un nom invente ferait",
  "rattacher les contacts d'une AUTRE societe, ce qui est pire que pas de resultat du tout.",
  '',
  'Reponds UNIQUEMENT par un objet JSON : {"nom":"<nom commercial>"} ou {"nom":"AUCUN"}.'
].filter(Boolean).join('\n');

return [{ json: Object.assign({}, soc, { prompt: prompt }) }];

// Meme mecanique que les autres appels IA : execFileSync sur le wrapper /usr/local/bin/claude-run,
// arguments en TABLEAU (pas de shell, donc aucune injection), timeout sous les 300 s du runner.
// Le jeton est lu par le wrapper dans le process fils : jamais visible ici.
const mod = require('child_process');
const entree = $input.first().json;

const cfg = $('Config').first().json;
const modele = cfg.MODELE_IA || 'sonnet';
const delai  = cfg.TIMEOUT_IA_MS || 270000;
const debut  = Date.now();

let sortie = '';
let sortieErreur = null;
let erreur = null;
let codeSortie = 0;

try {
  sortie = String(mod.execFileSync(
    'claude-run',
    ['-p', entree.prompt, '--output-format', 'json', '--model', modele],
    { encoding: 'utf8', timeout: delai, maxBuffer: 33554432, cwd: '/tmp' }
  ));
} catch (err) {
  // Quota epuise (429), jeton invalide, timeout : on n'echoue PAS le run. Le parseur en aval
  // constatera l'absence de nom, et la societe restera simplement en NO_MATCH.
  codeSortie = (err && typeof err.status === 'number') ? err.status : -1;
  erreur = String((err && err.message) || err).slice(0, 400);
  sortie = (err && err.stdout) ? String(err.stdout) : '';
  sortieErreur = (err && err.stderr) ? String(err.stderr).slice(0, 3000) : null;
}

return [{ json: Object.assign({}, entree, {
  sortie: sortie,
  sortieErreur: sortieErreur,
  erreur: erreur,
  codeSortie: codeSortie,
  dureeAppelMs: Date.now() - debut
})}];

// Depouille la reponse IA (double enveloppe : enveloppe CLI, puis JSON metier dans .result).
const e = $input.first().json;

let nom = '';
try {
  const env = JSON.parse(e.sortie || '{}');
  const txt = String(env.result || '');
  const d = txt.indexOf('{');
  const f = txt.lastIndexOf('}');
  if (d >= 0 && f > d) {
    const o = JSON.parse(txt.slice(d, f + 1));
    if (o.nom && String(o.nom).trim().toUpperCase() !== 'AUCUN') nom = String(o.nom).trim();
  }
} catch (err) { /* 429, sortie vide ou tronquee : pas de nom, on n'insiste pas */ }

// GARDE-FOU COUT : ne relancer Apollo que si le nom est REELLEMENT different. Sinon on paierait
// un 2e credit pour rejouer exactement la requete qui vient d'echouer.
const cle = s => String(s || '').toUpperCase().normalize('NFD')
  .replace(/[̀-ͯ]/g, '').replace(/[^A-Z0-9]/g, '');
const utile = !!nom && cle(nom) !== cle(e._nom_recherche);

return [{ json: Object.assign({}, e, {
  _nom_ia: nom,
  _nom_ia_ok: utile,
  _nom_ia_erreur: e.erreur || null,
  _nom_recherche: utile ? nom : e._nom_recherche
})}];

// FRANCE D'ABORD, etranger en DERNIER RECOURS.
// On garde les contacts localises en France + ceux SANS pays renseigne. Si cela ne donne RIEN,
// on bascule sur les etrangers plutot que de rendre la societe vide : ils seront plafonnes a 5
// et signales "Contact FR non trouve" dans l'Annuaire.
//
// !! POURQUOI CE NOEUD S'APPELLE "Apollo - Personnes" alors que l'appel HTTP s'appelle
// "Apollo - Personnes brut" : "Classer prospects" et "Sonde motif" vont chercher les personnes
// par $('Apollo - Personnes') en plus de leur entree normale. Ils COURT-CIRCUITAIENT donc le
// filtre (mesure du 07/08 : British Airways, 4 contacts gardes mais 104 vus au classement).
// En portant ce nom, le filtre s'intercale sans toucher aux 300 lignes de "Classer prospects".
// Ne pas renommer sans corriger ces deux noeuds.
const PAYS = ($('Config').first().json.PAYS || ['France'])
  .map(p => String(p).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, ''));
const MAX_REPLI = $('Config').first().json.MAX_REPLI_ETRANGER ?? 25;

return $input.all().map(item => {
  const src = (item.json && item.json.body) ? item.json.body : (item.json || {});
  const gens = src.people || [];
  const fr = [], inconnus = [], etrangers = [];

  for (const p of gens) {
    const loc = [p.country, p.state, p.city, p.present_raw_address]
      .filter(Boolean).join(' ').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
    if (!loc.trim()) { inconnus.push(p); continue; }
    if (PAYS.some(x => loc.indexOf(x) !== -1)) { fr.push(p); continue; }
    etrangers.push(p);
  }

  const retenus = fr.concat(inconnus);
  const repli = retenus.length === 0 && etrangers.length > 0;
  const people = repli ? etrangers.slice(0, MAX_REPLI) : retenus;

  return { json: Object.assign({}, src, {
    people: people,
    _loc_vus: gens.length,
    _loc_gardes: people.length,
    _loc_france: fr.length,
    _loc_sans_localisation: inconnus.length,
    _loc_hors_france: etrangers.length,
    _fallback_hors_france: repli,
  })};
});

// Meme regle que "Apollo - Personnes" (France + pays inconnu, etrangers en dernier recours),
// appliquee aux 12 requetes ciblees.
//
// Rappel : chaque bloc de fonctions est joue deux fois, avec et sans person_locations. La passe
// SANS pays sert a rattraper les profils dont le pays n'est pas renseigne : on ne garde d'eux que
// ceux effectivement sans pays, jamais un contact affiche a l'etranger.
const PAYS = ($('Config').first().json.PAYS || ['France'])
  .map(p => String(p).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, ''));
const MAX_REPLI = $('Config').first().json.MAX_REPLI_ETRANGER ?? 25;

return $input.all().map(item => {
  const src = (item.json && item.json.body) ? item.json.body : (item.json || {});
  const gens = src.people || [];
  const fr = [], inconnus = [], etrangers = [];

  for (const p of gens) {
    const loc = [p.country, p.state, p.city, p.present_raw_address]
      .filter(Boolean).join(' ').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
    if (!loc.trim()) { inconnus.push(p); continue; }
    if (PAYS.some(x => loc.indexOf(x) !== -1)) { fr.push(p); continue; }
    etrangers.push(p);
  }

  const retenus = fr.concat(inconnus);
  const repli = retenus.length === 0 && etrangers.length > 0;
  const people = repli ? etrangers.slice(0, MAX_REPLI) : retenus;

  return { json: Object.assign({}, src, {
    people: people,
    _loc_vus: gens.length,
    _loc_gardes: people.length,
    _loc_france: fr.length,
    _loc_sans_localisation: inconnus.length,
    _loc_hors_france: etrangers.length,
    _fallback_hors_france: repli,
  })};
});
